export default function RegisterClient({
  registrationEnabled,
  requiredLaunchState,
  gateReason,
  errorCode,
}: {
  registrationEnabled: boolean;
  requiredLaunchState: string;
  gateReason: string;
  errorCode: string;
}) {
  if (!registrationEnabled) {
    return (
